import React, { useState } from 'react';
import { TextField, Button, Box, Typography, Paper } from '@mui/material';
import { useNavigate } from 'react-router-dom';

const API = process.env.REACT_APP_API_URL || "http://localhost:5000/api";

export default function Login() {
  const [form, setForm] = useState({ email: '', password: '' });
  const [msg, setMsg] = useState('');
  const navigate = useNavigate();

  const handleChange = e => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMsg('');
    try {
      const res = await fetch(`${API}/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form)
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.msg || 'Login failed');

      localStorage.setItem('token', data.token);
      localStorage.setItem('user', JSON.stringify(data.user));
      setMsg('Login successful!');
      navigate('/'); // Go to Feed page
    } catch (err) {
      setMsg(err.message);
    }
  };

  return (
    <Paper elevation={3} sx={{ p: 4, maxWidth: 400, mx: 'auto', mt: 5 }}>
      <Typography variant="h5" sx={{ mb: 2 }}>Login</Typography>
      <form onSubmit={handleSubmit}>
        <TextField label="Email" name="email" type="email" fullWidth value={form.email} onChange={handleChange} sx={{ mb: 2 }} />
        <TextField label="Password" name="password" type="password" fullWidth value={form.password} onChange={handleChange} sx={{ mb: 3 }} />
        <Button type="submit" variant="contained" fullWidth>Login</Button>
      </form>
      {msg && <Typography color="primary" sx={{ mt: 2 }}>{msg}</Typography>}
    </Paper>
  );
}
